import{_ as a}from"./chunks/09-click-journey.Bm3gdwGl.js";import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.Dbgp30TS.js";const g=JSON.parse('{"title":"09 · 终幕：一次点击的完整旅程","description":"","frontmatter":{},"headers":[],"relativePath":"comics/09-click-journey.md","filePath":"comics/09-click-journey.md","lastUpdated":1794291790000}'),n={name:"comics/09-click-journey.md"};function c(i,e,p,l,d,u){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="_09-·-终幕-一次点击的完整旅程" tabindex="-1">09 · 终幕：一次点击的完整旅程 <a class="header-anchor" href="#_09-·-终幕-一次点击的完整旅程" aria-label="Permalink to &quot;09 · 终幕：一次点击的完整旅程&quot;">​</a></h1><p><img src="'+a+`" alt="一次点击的全链路：触摸→事件管线→React→commit→上屏"></p><p>九幕演完，到了串场谢幕。这一章没有新知识——只有<strong>全链路</strong>：当用户点下一个按钮，前面认识的每一位演员如何在一帧之内接力跑完一圈。</p><h2 id="一、第-1-3-站-事件进山洞" tabindex="-1">一、第 1~3 站：事件进山洞 <a class="header-anchor" href="#一、第-1-3-站-事件进山洞" aria-label="Permalink to &quot;一、第 1~3 站：事件进山洞&quot;">​</a></h2><p>手指落下的瞬间，系统触摸事件先在<strong>原生 UI 线程</strong>被捕获。06 章的触控管家 Pressability 在 JS 侧等着（[Pressability.js:L371](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Pressability/Pressability.js#L371) 起的默认导出类），但事件并不直接去 JS——它先进 C++ 的<strong>事件管线</strong>，由 [EventDispatcher.cpp:L26](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/core/EventDispatcher.cpp#L26) 的 <code>dispatchEvent</code> 按 target 视图把事件与影子树里的 tag 对上号，再经 JSI 直呼 <code>ReactFabric</code>（该模块在 [ReactFabric.js:L30](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/Libraries/Renderer/shims/ReactFabric.js#L30) 通过 <code>registerCallableModule</code> 登记为&quot;原生可回调&quot;）。</p><blockquote><p>事件为什么过 C++ 而不过旧 Bridge？因为新架构里 C++ 是<strong>中立的裁判</strong>：它同时认识原生视图和 React 树，谁都不用绕路。这就是&quot;同步可达&quot;的物理基础。</p></blockquote><h2 id="二、第-4-5-站-react-接单-fabric-排产" tabindex="-1">二、第 4~5 站：React 接单，Fabric 排产 <a class="header-anchor" href="#二、第-4-5-站-react-接单-fabric-排产" aria-label="Permalink to &quot;二、第 4~5 站：React 接单，Fabric 排产&quot;">​</a></h2><p>JS 线程上，React 调度器处理你 setState 里的更新（并发模式下还能被打断、让位给更紧急的事件）。算完新树，交稿给 Fabric：<code>UIManager.completeSurface</code>（[UIManager.cpp:L191](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/uimanager/UIManager.cpp#L191)，05 章第二站）。</p><p>影子树 commit 在 [ShadowTree.cpp:L303](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/mounting/ShadowTree.cpp#L303)：若同时有别的更新在跑，<strong>带版本重试</strong>；成功后 Yoga 就地布局。</p><h2 id="三、第-6-7-站-拆单与上屏" tabindex="-1">三、第 6~7 站：拆单与上屏 <a class="header-anchor" href="#三、第-6-7-站-拆单与上屏" aria-label="Permalink to &quot;三、第 6~7 站：拆单与上屏&quot;">​</a></h2><p>Differentiator 在 [Differentiator.cpp:L122](file:///Users/yangzhijie/Desktop/practice_projects/claude-code-test/_rn-source/react-native-0.87.1/ReactCommon/react/renderer/mounting/Differentiator.cpp#L122) 的 <code>calculateShadowViewMutations</code> 拆出五种指令（CREATE / INSERT / UPDATE / REMOVE / DELETE），MountingCoordinator 基于 revision 推进。指令回到<strong>原生 UI 线程</strong>：Android 的 FabricUIManager、iOS 的 RCTViewComponentView 逐条执行——按钮高亮、文字变化，屏幕上的像素更新完毕。</p><h2 id="四、第-8-站-回声" tabindex="-1">四、第 8 站：回声 <a class="header-anchor" href="#四、第-8-站-回声" aria-label="Permalink to &quot;四、第 8 站：回声&quot;">​</a></h2><p>commit 收尾回发 layout events。如果你的代码里有 <code>onLayout</code>，它会<strong>晚一拍</strong>回到 JS——这就是&quot;onLayout 里改状态必然多一帧&quot;的原理。同理，Text 的测量回包也是这条回声路径。</p><h2 id="五、一帧之内" tabindex="-1">五、一帧之内 <a class="header-anchor" href="#五、一帧之内" aria-label="Permalink to &quot;五、一帧之内&quot;">​</a></h2><p>把线程速查再念一遍：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原生 UI 线程：触摸捕获、最终上屏（起点与终点）</span></span>
<span class="line"><span>C++ 渲染线程：事件路由、commit、布局、diff（中转枢纽）</span></span>
<span class="line"><span>JS 线程：     React 调度、你的业务逻辑（决策层）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>三者像三班倒的工厂：<strong>上一棒不堵下一棒</strong>。当动画卡顿，先问是哪一棒堵了——这正是 09 章给你的调试坐标系。</p><h2 id="六、faq" tabindex="-1">六、FAQ <a class="header-anchor" href="#六、faq" aria-label="Permalink to &quot;六、FAQ&quot;">​</a></h2><p><strong>Q1：点击到上屏一共跨几次语言边界？</strong> 事件进 JS 一次（native→C++→JS），渲染回 native 一次（JS→C++→native），共两次&quot;大跨界&quot;。比旧 Bridge 的 JSON 序列化轻一个数量级。</p><p><strong>Q2：为什么交互时 setState 不 Immediately 生效？</strong> React 需要一个批处理窗口来合并同一帧内的多次更新；新架构把窗口压缩到极短，但&quot;合批&quot;本身是正确性的来源。</p><p><strong>Q3：如何实测这一圈多长？</strong> Dev Menu → &quot;Show Perf Monitor&quot;，或用 RN DevTools 的 Timeline；再用 <code>InteractionManager</code> 在业务侧打点对照。</p><hr><blockquote><p>全剧终。去 <a href="./../tutorial/01-setup">Part II 实战教程</a>把这些知识亲手跑起来——或者回 <a href="./00-intro">00 导读</a>换个路线再读一遍源码。</p></blockquote>`,23)])])}const b=t(n,[["render",c]]);export{g as __pageData,b as default};
